mapper.insert:
INSERT INTO MEMBER (
  MEM_ID
  , MEM_PW
  , MEM_NAME
  , ROLE
) VALUES (
  #{memId}
  , #{memPw}
  , #{memName}
  , 'repairman'
)

INSERT INTO ENGINEER (
  MEM_NO
  , ENGINEER_NAME
  , ENGINEER_TEL
  , SPECIALTY
  , WORK_START_TIME
  , WORK_END_TIME
  , STATUS
) VALUES (
  #{memNo}
  , #{engineerName}
  , #{engineerTel}
  , #{specialty}
  , #{workStartTime}
  , #{workEndTime}
  , #{status}
)

mapper.update:
UPDATE ENGINEER
SET ENGINEER_NAME   = #{engineerName}
  , ENGINEER_TEL    = #{engineerTel}
  , SPECIALTY       = #{specialty}
  , WORK_START_TIME = #{workStartTime}
  , WORK_END_TIME   = #{workEndTime}
  , STATUS          = #{status}
WHERE ENGINEER_NO = #{engineerNo}
